/**
 * Day 20 — Binary Search Tree. Original statements + reference solutions for
 * the in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 */

function buildTree(serial) {
  const tokens = serial.trim().split(/\s+/);
  if (!tokens.length || tokens[0] === 'null') return null;
  const root = { val: Number(tokens[0]), raw: tokens[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  while (queue.length && i < tokens.length) {
    const node = queue.shift();
    if (i < tokens.length) {
      const t = tokens[i++];
      if (t !== 'null') { node.left = { val: Number(t), raw: t, left: null, right: null }; queue.push(node.left); }
    }
    if (i < tokens.length) {
      const t = tokens[i++];
      if (t !== 'null') { node.right = { val: Number(t), raw: t, left: null, right: null }; queue.push(node.right); }
    }
  }
  return root;
}

function serialize(root) {
  if (!root) return 'null';
  const out = [];
  const queue = [root];
  while (queue.length) {
    const node = queue.shift();
    if (!node) { out.push('null'); continue; }
    out.push(node.val);
    queue.push(node.left);
    queue.push(node.right);
  }
  while (out.length && out[out.length - 1] === 'null') out.pop();
  return out.join(' ');
}

function inorder(node, out = []) {
  if (!node) return out;
  inorder(node.left, out);
  out.push(node);
  inorder(node.right, out);
  return out;
}

